# Render the fixed gate outcomes without changing calibration or simulation.
if(dir.exists('.local/R-library')) .libPaths(c(normalizePath('.local/R-library'),.libPaths()))
source('R/scp_calibrate.R');started<-proc.time()[['elapsed']];out<-'reports/M2b'
s<-read.csv(file.path(out,'fidelity-summary.csv'));checks<-read.csv(file.path(out,'fidelity-table.csv'));reps<-read.csv(file.path(out,'replicate-metrics.csv'));obs<-read.csv(file.path(out,'observed-metrics.csv'));bins<-read.csv(file.path(out,'missingness-intensity-bins.csv'))
m<-jsonlite::read_json(file.path(out,'run-manifest.json'),simplifyVector=FALSE);vt<-paste(names(.scp_versions()),.scp_versions(),sep='=',collapse='; ')
footer<-function(){mtext('Registered native designs; beta=0; 20 independent replicates; no calibration or simulator retuning.',side=1,outer=TRUE,line=1,cex=.65,xpd=NA);mtext(vt,side=1,outer=TRUE,line=2.2,cex=.48,xpd=NA)}
png(file.path(out,'missingness-observed-simulated.png'),width=2100,height=950,res=180);par(mfrow=c(1,3),mar=c(4,4,4,1),oma=c(4,0,2,0))
for(n in s$dataset){o<-obs[obs$dataset==n,];r<-reps[reps$dataset==n,];average<-vapply(o$tier,function(t)mean(r$missing_fraction[r$tier==t]),numeric(1));plot(0,0,type='n',xlim=c(0,1),ylim=c(0,1),xlab='Observed endpoint missing fraction',ylab='Simulated mean missing fraction',main=n);polygon(c(0,1,1,0),c(.05,1.05,.95,-.05),col='#E6EDF2',border=NA);abline(0,1,col='gray');points(o$missing_fraction,average,pch=16,col='#1680a1');text(o$missing_fraction,average,labels=o$tier,pos=3,cex=.8);mtext(s$status[s$dataset==n],side=3,line=.2,col=if(s$status[s$dataset==n]=='PASS')'#216b38' else '#b22222',cex=.8)}
plot.new();legend('center',legend=c('Fixed abundance tiers','Band = registered 5 pp tolerance'),pch=c(16,NA),col=c('#1680a1','gray'),bty='n',cex=.9);footer();dev.off()
png(file.path(out,'cell-sd-observed-simulated.png'),width=2100,height=950,res=180);par(mfrow=c(1,3),mar=c(4,4,4,1),oma=c(4,0,2,0))
for(n in s$dataset){o<-obs[obs$dataset==n,];r<-reps[reps$dataset==n,];average<-vapply(o$tier,function(t)mean(r$cell_sd[r$tier==t]),numeric(1));variation<-vapply(o$tier,function(t)sd(r$cell_sd[r$tier==t]),numeric(1));plot(o$tier,o$cell_sd,pch=16,col='#1680a1',ylim=c(0,max(c(o$cell_sd,average+variation),na.rm=TRUE)*1.1),xlab='Accepted abundance tier',ylab='Median within-line cell SD (log2)',main=n);points(o$tier+.08,average,pch=17,col='#b85555');arrows(o$tier+.08,average-variation,o$tier+.08,average+variation,angle=90,code=3,length=.04,col='#b85555');par(xpd=NA);title(main=n);mtext(s$status[s$dataset==n],side=3,line=.2,col=if(s$status[s$dataset==n]=='PASS')'#216b38' else '#b22222',cex=.8,xpd=NA);par(xpd=FALSE)}
plot.new();legend('center',legend=c('Observed','Simulated mean; bars = replicate SD'),pch=c(16,17),col=c('#1680a1','#b85555'),bty='n',cex=.85);footer();dev.off()
f<-function(x,d=3)ifelse(is.finite(x),format(round(x,d),nsmall=d,trim=TRUE),'NA')
lines<-c('# M2b simulator fidelity report — amendment I','13 October 2026. Frozen addendum v1.1.5. Every dataset uses its exact cell-line-by-acquisition-batch counts and beta=0. Each comparison averages the registered independent replicates. Every applicable tier must pass; no failing tier is averaged away.','', '| Dataset | Gate | Missingness maximum error (pp) | Coverage relative error | Cell SD maximum relative error | Batch SD maximum relative error |','| --- | --- | ---: | ---: | ---: | ---: |')
for(i in seq_len(nrow(s)))lines<-c(lines,sprintf('| %s | %s | %s | %s%% | %s%% | %s |',s$dataset[i],s$status[i],f(100*s$maximum_missingness_error[i],2),f(100*s$coverage_relative_error[i],1),f(100*s$maximum_cell_sd_error[i],1),if(is.finite(s$maximum_batch_sd_error[i]))paste0(f(100*s$maximum_batch_sd_error[i],1),'%') else 'Not applicable (F)'))
lines<-c(lines,'','Registered tolerances: missing fraction per tier within 5 percentage points; proteins per cell within 10% relative; median within-line cell SD per tier within 20% relative; between-batch SD per tier within 25% relative where separately identified. Only the two TMT datasets are rerun.','', 'The [full fidelity table](fidelity-table.csv) gives observed values, simulated means, errors, tolerances and PASS/FAIL for every quantity and tier. [Replicate metrics](replicate-metrics.csv) preserve all draws and seeds.','', 'Suspected causes are interpretations of these fixed outcomes, not changes to the implementation:','')
for(n in s$dataset) {
 bad<-checks[checks$dataset==n&checks$applicable&!checks$pass,]
 if(!nrow(bad))lines<-c(lines,paste0('- ',n,': PASS on all applicable quantities.')) else {
  cause<-character();if(any(bad$metric=='missing_fraction'))cause<-c(cause,if(n%in%c('specht2019v3','leduc2022_pSCoPE'))'a single protein-specific p_g/q_g pair across cell lines omits line-specific identification and channel heterogeneity; unequal native plex sizes can make the unweighted p_g and channel-weighted q_g reproduce a different coverage than the endpoint mask' else 'protein-specific baseline rates are shifted by sample and batch effects through a nonlinear logit; baseline r_g is marginal over the observed cell population, so additional intensity fluctuations need not preserve its marginal detection rate')
  if(any(bad$metric=='mean_proteins_per_cell'))cause<-c(cause,'heterogeneous native plex occupancy or expected-intensity shifts can change marginal total coverage under the registered detection structure')
  if(any(bad$metric=='cell_sd'))cause<-c(cause,'joint protein resampling removes tier averaging, but calibrated conditional residual variance and latent batch variance need not reconstruct the observed within-line SD after detection and median normalization; random missingness omits protein-by-line measurement structure')
  if(any(bad$metric=='batch_sd'))cause<-c(cause,'calibrated latent per-protein batch variance need not reconstruct SD of noisy batch means under sparse detection, plex identification and line-mean removal; fitting a random batch component and measuring raw batch means are different operations')
  lines<-c(lines,paste0('- ',n,': FAIL; ',paste(unique(cause),collapse='; '),'.'))
 }
}
lines<-c(lines,'', 'The accepted M1 estimates, including Specht\'s weak negative raw-intensity slope, are unchanged. Amendment G replaces TMT curve masking with plex p_g then conditional channel q_g draws; I changes only their mask source to the endpoint assay, independent of effect size. For DIA and label-free data, protein r_g supplies baseline detection and the fitted curve supplies only the slope. Parameters were fixed before this rerun; no adjustment follows its outcomes. If any series fails, M4b and the v0.3.1 tag remain unauthorised and work stops after this report.','', 'Missingness and coverage use the endpoint aggregated assay mask for TMT under I ; non-TMT results are unchanged and not rerun. Cell SD uses the accepted variance assay after per-cell median shifts; the same shift is applied to simulations. It is the median over measured protein-by-line SDs within each tier. Batch SD is the median of protein-level SDs across mixed-batch means after line-mean subtraction. The missingness figure shows fixed-tier gate statistics and the registered 5-pp band; no smoothing or calibration adjustment is applied.','', 'Cell lines are culture samples. The injected Walzik variance remains a whole-PBMC proxy, including donor composition differences; M2 cannot validate bulk-to-cell-line donor transfer. The registered M4 criterion is unchanged.','', paste('Software:',vt))
half<-read.csv(file.path(out,'half-cells-detection.csv'))
lines<-c(lines,'','## Additional descriptive quantity (outside the gate)','',
 '| Dataset | Observed fraction quantified in at least half the cells | Simulated mean | Replicate SD |',
 '| --- | ---: | ---: | ---: |')
for(i in seq_len(nrow(half)))lines<-c(lines,sprintf('| %s | %s | %s | %s |',half$dataset[i],f(half$observed[i],4),f(half$simulated_mean[i],4),f(half$simulated_sd[i],4)))
lines<-c(lines,'','This descriptive quantity does not alter the gate. TimsTOF, Q Exactive and Brunner are not rerun. This quantity has no tolerance and cannot change PASS/FAIL. Registered consequence: TMT carrier pools both conditions, so p_g and q_g do not respond to effect size; testability depends on plex count and barely on effect size.','', 'Per-protein parameter tables and preset hashes are saved alongside the report. Undefined means for never-detected proteins use a documented tier fallback while retaining zero detection; unmapped donor variances and missing protein component estimates use the registered tier fallback. The calibration itself is not changed.')
writeLines(lines,file.path(out,'fidelity-report.md'))
writeLines(c('# M2 evidence','', '[Fidelity report](fidelity-report.md), [full gate table](fidelity-table.csv), [summary](fidelity-summary.csv), [missingness plot](missingness-observed-simulated.png), [cell SD plot](cell-sd-observed-simulated.png), [run manifest](run-manifest.json).','', 'The gate is reported without tuning. A failed dataset stops; the next directive determines any change. Simulator tests and package CI are separate from scientific fidelity outcomes.'),file.path(out,'README.md'))
m$report_generation<-list(seed=20261013,versions=as.list(.scp_versions()),input_hashes=list(gate_table=digest::digest(file=file.path(out,'fidelity-table.csv'),algo='sha256'),replicate_metrics=digest::digest(file=file.path(out,'replicate-metrics.csv'),algo='sha256')),wall_seconds=proc.time()[['elapsed']]-started)
m$decision<-list(status='Completed registered M2b gate; all failures reported without tuning',passed_datasets=as.list(s$dataset[s$status=='PASS']),failed_datasets=as.list(s$dataset[s$status=='FAIL']),M4b_authorised=all(s$status=='PASS'),v0_3_1_requires_M4b=TRUE,non_TMT_results_not_rerun=TRUE)
jsonlite::write_json(m,file.path(out,'run-manifest.json'),pretty=TRUE,auto_unbox=TRUE,na='null',digits=NA)
